//! Integration tests for the prost-generated canal protocol types.
//! The generated file is regenerated by build.rs, so tests live here.
use canal_proto::*;
use prost::Message;

fn roundtrip<T: Message + Default + PartialEq + std::fmt::Debug>(msg: &T) -> T {
    let bytes = msg.encode_to_vec();
    let decoded = T::decode(bytes.as_slice()).expect("decode should succeed");
    assert_eq!(&decoded, msg, "roundtrip mismatch");
    decoded
}

// ---------- Packet ----------

#[test]
fn test_packet_roundtrip_all_fields() {
    let packet = Packet {
        r#type: PacketType::Get as i32,
        body: vec![1, 2, 3, 4],
        magic_number_present: Some(packet::MagicNumberPresent::MagicNumber(17)),
        version_present: Some(packet::VersionPresent::Version(1)),
        compression_present: Some(packet::CompressionPresent::Compression(
            Compression::Zlib as i32,
        )),
    };
    roundtrip(&packet);
}

#[test]
fn test_packet_default() {
    let packet = Packet::default();
    assert_eq!(packet.r#type, 0);
    assert_eq!(
        PacketType::try_from(packet.r#type).unwrap(),
        PacketType::Packagetypecompatibleproto2
    );
    assert!(packet.body.is_empty());
    assert!(packet.magic_number_present.is_none());
    assert!(packet.version_present.is_none());
    assert!(packet.compression_present.is_none());
}

#[test]
fn test_packet_decode_truncated_errors() {
    // Truncated varint for tag 3 field type
    assert!(Packet::decode(&[0x18u8][..]).is_err());
    // Completely empty buffer decodes to default
    let p = Packet::decode(&[][..]).unwrap();
    assert_eq!(p, Packet::default());
}

// ---------- Handshake / ClientAuth / Ack ----------

#[test]
fn test_handshake_roundtrip() {
    let hs = Handshake {
        seeds: vec![0xde, 0xad, 0xbe, 0xef],
        supported_compressions: Compression::Gzip as i32,
        communication_encoding_present: Some(
            handshake::CommunicationEncodingPresent::CommunicationEncoding("utf8".into()),
        ),
    };
    roundtrip(&hs);
    // Default: no encoding present
    assert!(Handshake::default()
        .communication_encoding_present
        .is_none());
}

#[test]
fn test_client_auth_roundtrip() {
    let auth = ClientAuth {
        username: "canal".into(),
        password: vec![1, 2, 3],
        destination: "example".into(),
        client_id: "1001".into(),
        filter: ".*\\..*".into(),
        start_timestamp: 1700000000,
        net_read_timeout_present: Some(client_auth::NetReadTimeoutPresent::NetReadTimeout(30)),
        net_write_timeout_present: Some(client_auth::NetWriteTimeoutPresent::NetWriteTimeout(30)),
    };
    roundtrip(&auth);
    assert!(ClientAuth::default().net_read_timeout_present.is_none());
}

#[test]
fn test_ack_roundtrip() {
    let ack_ok = Ack {
        error_message: String::new(),
        error_code_present: None,
    };
    roundtrip(&ack_ok);
    let ack_err = Ack {
        error_message: "compression not supported".into(),
        error_code_present: Some(ack::ErrorCodePresent::ErrorCode(1)),
    };
    roundtrip(&ack_err);
}

