// ---------- Sub / Unsub / Get / Messages / Dump / ClientRollback ----------

#[test]
fn test_sub_unsub_roundtrip() {
    let sub = Sub {
        destination: "example".into(),
        client_id: "1001".into(),
        filter: "test_db\\.users".into(),
    };
    roundtrip(&sub);
    let unsub = Unsub {
        destination: "example".into(),
        client_id: "1001".into(),
        filter: "test_db\\.users".into(),
    };
    roundtrip(&unsub);
}

#[test]
fn test_get_roundtrip_all_oneofs() {
    let get = Get {
        destination: "example".into(),
        client_id: "1001".into(),
        fetch_size: 100,
        timeout_present: Some(get::TimeoutPresent::Timeout(-1)),
        unit_present: Some(get::UnitPresent::Unit(2)),
        auto_ack_present: Some(get::AutoAckPresent::AutoAck(true)),
    };
    roundtrip(&get);
    // Defaults: no oneof fields present
    let d = Get::default();
    assert!(d.timeout_present.is_none());
    assert!(d.unit_present.is_none());
    assert!(d.auto_ack_present.is_none());
}

#[test]
fn test_messages_roundtrip() {
    let msgs = Messages {
        batch_id: 7,
        messages: vec![vec![1, 2], vec![], vec![0xff, 0x00]],
    };
    roundtrip(&msgs);
    assert_eq!(msgs.messages.len(), 3);
}

