// ---------- Entry / Header / Column / RowChange ----------

#[test]
fn test_entry_roundtrip_with_header() {
    let entry = Entry {
        header: Some(Header {
            logfile_name: "mysql-bin.000001".into(),
            logfile_offset: 120,
            server_id: 1,
            serveren_code: "utf8".into(),
            execute_time: 1700000000,
            schema_name: "test_db".into(),
            table_name: "users".into(),
            event_length: 1024,
            props: vec![Pair {
                key: "k".into(),
                value: "v".into(),
            }],
            gtid: "uuid:1-10".into(),
            version_present: Some(header::VersionPresent::Version(1)),
            source_type_present: Some(header::SourceTypePresent::SourceType(Type::Mysql as i32)),
            event_type_present: Some(header::EventTypePresent::EventType(
                EventType::Insert as i32,
            )),
        }),
        store_value: vec![0xab, 0xcd],
        entry_type_present: Some(entry::EntryTypePresent::EntryType(
            EntryType::Rowdata as i32,
        )),
    };
    let decoded = roundtrip(&entry);
    assert_eq!(
        decoded.header.unwrap().schema_name,
        "test_db",
        "schema name must survive roundtrip"
    );
}

#[test]
fn test_entry_default() {
    let e = Entry::default();
    assert!(e.header.is_none());
    assert!(e.store_value.is_empty());
    assert!(e.entry_type_present.is_none());
}

