#[test]
fn test_row_change_roundtrip() {
    let rc = RowChange {
        table_id: 42,
        sql: "ALTER TABLE t ADD COLUMN c INT".into(),
        row_datas: vec![RowData {
            before_columns: vec![],
            after_columns: vec![],
            props: vec![],
        }],
        props: vec![],
        ddl_schema_name: "test_db".into(),
        event_type_present: Some(row_change::EventTypePresent::EventType(
            EventType::Update as i32,
        )),
        is_ddl_present: Some(row_change::IsDdlPresent::IsDdl(true)),
    };
    roundtrip(&rc);
    // Default: UPDATE implied, is_ddl false
    let d = RowChange::default();
    assert!(d.event_type_present.is_none());
    assert!(d.is_ddl_present.is_none());
    assert!(d.sql.is_empty());
}

