// ---------- Enums ----------

#[test]
fn test_compression_enum_helpers() {
    for v in [
        Compression::Compressioncompatibleproto2,
        Compression::None,
        Compression::Zlib,
        Compression::Gzip,
        Compression::Lzf,
    ] {
        assert_eq!(Compression::from_str_name(v.as_str_name()), Some(v));
        assert_eq!(v as i32, Compression::try_from(v as i32).unwrap() as i32);
    }
    assert_eq!(Compression::from_str_name("BOGUS"), None);
    // Wire values are stable
    assert_eq!(Compression::None as i32, 1);
    assert_eq!(Compression::Zlib as i32, 2);
    assert_eq!(Compression::Gzip as i32, 3);
}

#[test]
fn test_packet_type_enum_helpers() {
    for v in [
        PacketType::Packagetypecompatibleproto2,
        PacketType::Handshake,
        PacketType::Clientauthentication,
        PacketType::Ack,
        PacketType::Subscription,
        PacketType::Unsubscription,
        PacketType::Get,
        PacketType::Messages,
        PacketType::Clientack,
        PacketType::Shutdown,
        PacketType::Dump,
        PacketType::Heartbeat,
        PacketType::Clientrollback,
    ] {
        assert_eq!(PacketType::from_str_name(v.as_str_name()), Some(v));
    }
    assert_eq!(PacketType::from_str_name("BOGUS"), None);
    // Wire values are stable
    assert_eq!(PacketType::Handshake as i32, 1);
    assert_eq!(PacketType::Heartbeat as i32, 11);
}

#[test]
fn test_entry_type_enum_helpers_and_wire_values() {
    for v in [
        EntryType::Entrytypecompatibleproto2,
        EntryType::Transactionbegin,
        EntryType::Rowdata,
        EntryType::Transactionend,
        EntryType::Innerheartbeat,
        EntryType::Gtidlog,
    ] {
        assert_eq!(EntryType::from_str_name(v.as_str_name()), Some(v));
    }
    assert_eq!(EntryType::from_str_name("BOGUS"), None);
    // Wire compatibility preserved after HEARTBEAT -> INNERHEARTBEAT rename
    assert_eq!(EntryType::Innerheartbeat as i32, 4);
    assert_eq!(EntryType::Rowdata as i32, 2);
}

#[test]
fn test_event_type_enum_helpers_and_wire_values() {
    for v in [
        EventType::Eventtypecompatibleproto2,
        EventType::Insert,
        EventType::Update,
        EventType::Delete,
        EventType::Create,
        EventType::Alter,
        EventType::Erase,
        EventType::Query,
        EventType::Truncate,
        EventType::Rename,
        EventType::Cindex,
        EventType::Dindex,
        EventType::Gtid,
        EventType::Xacommit,
        EventType::Xarollback,
        EventType::Mheartbeat,
    ] {
        assert_eq!(EventType::from_str_name(v.as_str_name()), Some(v));
    }
    assert_eq!(EventType::from_str_name("BOGUS"), None);
    // Wire values expected by canal_common::EventType::from_proto
    assert_eq!(EventType::Query as i32, 7);
    assert_eq!(EventType::Xacommit as i32, 13);
    assert_eq!(EventType::Mheartbeat as i32, 15);
}

#[test]
fn test_type_enum_helpers() {
    for v in [
        Type::Typecompatibleproto2,
        Type::Oracle,
        Type::Mysql,
        Type::Pgsql,
    ] {
        assert_eq!(Type::from_str_name(v.as_str_name()), Some(v));
    }
    assert_eq!(Type::from_str_name("BOGUS"), None);
    assert_eq!(Type::Mysql as i32, 2);
}

